import urllib.request

BASE = "http://pricing-v2.internal:8081/api/v2/price"


def get_price(sku: str) -> float:
    """Fetch a live price using the separately configured pricing credential."""
    key = os.environ.get("PRICING_API_KEY")
    if not key:
        raise RuntimeError("PRICING_API_KEY must be configured for the price service")
    request = urllib.request.Request(
        f"{BASE}/{urllib.parse.quote(sku, safe='')}",
        headers={"X-Pricing-Key": key},
    )
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(sku) for sku in skus)
